from AlgorithmImports import *
from collections import deque


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=2)

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.RegisterIndicator(self.aapl, self.aapl_rsi, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_red_streak = 0
        self.aapl_previous_rsi = None

    def OnData(self, data):
        spy_bar = data.Bars.get(self.spy)
        aapl_bar = data.Bars.get(self.aapl)

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_closes.append(spy_close)

            if len(self.spy_closes) >= 101:
                sma_today = sum(list(self.spy_closes)[-100:]) / 100.0

                if self.spy_previous_close is not None and self.spy_previous_sma is not None:
                    spy_cross_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > sma_today
                    )
                    spy_cross_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < sma_today
                    )
                else:
                    spy_cross_above = False
                    spy_cross_below = False

                current_sma = sma_today
            else:
                current_sma = None
                spy_cross_above = False
                spy_cross_below = False
        else:
            spy_cross_above = False
            spy_cross_below = False
            current_sma = None

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.aapl_closes:
                previous_aapl_close = self.aapl_closes[-1]
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_closes.append(aapl_close)

        if any(data.Bars.get(symbol) is None for symbol in self.symbols.values()):
            if spy_bar is not None and current_sma is not None:
                self.spy_previous_close = float(spy_bar.Close)
                self.spy_previous_sma = current_sma

            if self.aapl_rsi.IsReady:
                self.aapl_previous_rsi = float(self.aapl_rsi.Current.Value)

            return

        if spy_bar is not None and current_sma is not None:
            spy_close = float(spy_bar.Close)

            if self.strategy_a_lot > 0 and spy_cross_below:
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="Strategy A Sell"
                )
                self.strategy_a_lot = 0

            if self.strategy_a_lot == 0 and spy_cross_above:
                target_value = self.Portfolio.TotalPortfolioValue
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="Strategy A Buy"
                    )
                    self.strategy_a_lot = quantity

            self.spy_previous_close = spy_close
            self.spy_previous_sma = current_sma

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            rsi_ready = self.aapl_rsi.IsReady
            rsi_today = float(self.aapl_rsi.Current.Value) if rsi_ready else None

            if self.strategy_b_lot > 0 and rsi_ready and rsi_today > 60:
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B Sell"
                )
                self.strategy_b_lot = 0

            if (
                self.strategy_b_lot == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B Buy"
                    )
                    self.strategy_b_lot = quantity

            if rsi_ready:
                self.aapl_previous_rsi = rsi_today

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        if orderEvent.Symbol == self.spy:
            self.strategy_a_lot = max(0, self.strategy_a_lot + orderEvent.FillQuantity)

        elif orderEvent.Symbol == self.aapl:
            self.strategy_b_lot = max(0, self.strategy_b_lot + orderEvent.FillQuantity)
