        self.rsi_average_loss = None

        self._SeedHistory()

    def _SeedHistory(self):
        for symbol, target in [
            (self.spy, self.spy_closes),
            (self.aapl, self.aapl_closes)
        ]:
            history = self.History[TradeBar](symbol, 120, Resolution.Daily)
            for bar in history:
                target.append(float(bar.Close))

        if len(self.aapl_closes) >= 2:
            closes = list(self.aapl_closes)
            deltas = [
                closes[i] - closes[i - 1]
                for i in range(1, len(closes))
            ]

            if len(deltas) >= self.rsi_period:
                initial = deltas[:self.rsi_period]
                self.rsi_average_gain = sum(max(x, 0) for x in initial) / self.rsi_period
                self.rsi_average_loss = sum(max(-x, 0) for x in initial) / self.rsi_period

                for delta in deltas[self.rsi_period:]:
                    gain = max(delta, 0)
                    loss = max(-delta, 0)
                    self.rsi_average_gain = (
                        (self.rsi_average_gain * (self.rsi_period - 1) + gain)
                        / self.rsi_period
                    )
                    self.rsi_average_loss = (
                        (self.rsi_average_loss * (self.rsi_period - 1) + loss)
                        / self.rsi_period
                    )

                self.aapl_rsi = self._CalculateRsi(
                    self.rsi_average_gain,
                    self.rsi_average_loss
                )

    def _CalculateRsi(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0
        relative_strength = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

