                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

        if len(self.aapl_closes) >= 4:
            aapl_closes = list(self.aapl_closes)
            red_three_days = (
                aapl_closes[-1] < aapl_closes[-2]
                and aapl_closes[-2] < aapl_closes[-3]
                and aapl_closes[-3] < aapl_closes[-4]
            )

            if self.aapl_lot > 0:
                if self.aapl_rsi is not None and self.aapl_rsi > 60:
