            elif red_three_days and self.Portfolio.Cash >= 20000:
                quantity = int(math.floor(20000 / aapl_closes[-1]))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity
